c('SLC35C1', [('SLC','SoLute Carrier (famille de transporteurs)'),('35C1','famille 35, membre C1')], 'Gène du transporteur du GDP-fucose', 'Gène du LAD-II, dont le défaut empêche la fucosylation des ligands des sélectines.', 'd71-lad')
